/**
 * Gmail Node - Version 2
 * Discriminator: resource=label, operation=get
 */


interface Credentials {
  googleApi: CredentialReference;
  gmailOAuth2: CredentialReference;
}

export type GmailV2LabelGetParams = {
  resource: 'label';
  operation: 'get';
  authentication?: 'oAuth2' | 'serviceAccount' | Expression<string>;
/**
 * The ID of the label
 */
    labelId: string | Expression<string>;
};

export type GmailV2LabelGetOutput = {
  id?: string;
  labelListVisibility?: string;
  messageListVisibility?: string;
  messagesTotal?: number;
  messagesUnread?: number;
  name?: string;
  threadsTotal?: number;
  threadsUnread?: number;
  type?: string;
};

export type GmailV2LabelGetNode = {
  type: 'n8n-nodes-base.gmail';
  version: 2;
  config: NodeConfig<GmailV2LabelGetParams> & { credentials?: Credentials };
  output?: Items<GmailV2LabelGetOutput>;
};